head.script:
//
{
  "@context": "https://schema.org",
  "@type": "WebSite",
  "name": "TNHub Tây Ninh",
  "url": "https://www.tayninhinfo.com/",
  "description": "Cổng thông tin việc làm, bất động sản và video khám phá tỉnh Tây Ninh"
}
//

//
(function(){
  try {
    const origWarn = console.warn;
    console.warn = function() {
      if (arguments[0] && typeof arguments[0] === 'string' && arguments[0].indexOf('cdn.tailwindcss.com') !== -1) {
        return;
      }
      origWarn.apply(console, arguments);
    };
  } catch(e) {}
})();
//

tailwind.config = {
  darkMode: 'class',
  theme: {
    extend: {
      colors: {
        oracle: {
          red: '#C74634',
          hover: '#B13C2C',
          dark: '#161513',
          warm: '#F1EFED',
          border: '#E0DDD8',
          charcoal: '#312E2B',
          yellow: '#F1B13F'
        },
        tnhub: {
          50: '#fdf3f2',
          100: '#fbe4e2',
          500: '#C74634',
          600: '#B13C2C',
          700: '#9B3325',
          800: '#7E2A1E',
          900: '#161513'
        }
      }
    }
  }
}

head.b:skin:
* {
  border-radius: 0px !important;
}
body {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  height: 100vh;
  height: 100dvh;
  width: 100vw;
  overflow: hidden;
  background-color: #F1EFED;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #161513;
  display: flex;
}
@media (min-width: 768px) {
  body {
    padding: 16px;
  }
}
@media (min-width: 1024px) {
  body {
    padding: 20px;
  }
}
.custom-scroll::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
.custom-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.custom-scroll::-webkit-scrollbar-thumb {
  background: #C74634;
  border-radius: 0px !important;
}
[v-cloak] {
  display: none !important;
}

div.v-bind:class:
{
             "bg-emerald-50 border-emerald-500 text-emerald-900": toast.type === "success",
             "bg-rose-50 border-rose-500 text-rose-900": toast.type === "error",
             "bg-amber-50 border-amber-500 text-amber-900": toast.type === "warning",
             "bg-blue-50 border-blue-500 text-blue-900": toast.type === "info"
           }

{
               "bg-emerald-100 text-emerald-600": popup.type === "success",
               "bg-rose-100 text-rose-600": popup.type === "error",
               "bg-amber-100 text-amber-600": popup.type === "warning",
               "bg-blue-100 text-blue-600": popup.type === "info"
             }

button.v-bind:class:
{
                    "bg-slate-900 hover:bg-slate-800 text-white": popup.type === "success" || popup.type === "info",
                    "bg-rose-600 hover:bg-rose-700 text-white": popup.type === "error",
                    "bg-amber-600 hover:bg-amber-700 text-white": popup.type === "warning"
                  }

body.script:
//
import { initializeApp } from 'https://www.gstatic.com/firebasejs/10.9.0/firebase-app.js';
import { 
  getAuth, 
  GoogleAuthProvider, 
  signInWithPopup, 
  signOut, 
  onAuthStateChanged 
} from 'https://www.gstatic.com/firebasejs/10.9.0/firebase-auth.js';
import { 
  getFirestore,
  initializeFirestore, 
  collection, 
  addDoc, 
  deleteDoc,
  query, 
  orderBy, 
  limit, 
  onSnapshot, 
  doc, 
  setDoc, 
  serverTimestamp 
} from 'https://www.gstatic.com/firebasejs/10.9.0/firebase-firestore.js';

// For Firebase JS SDK v7.20.0 and later, measurementId is optional
const firebaseConfig = {
  apiKey: "AIzaSyB36E4W7BG8ZLQnfBLeZu-pVtf4TVDqLUQ",
  authDomain: "fir-1b417.firebaseapp.com",
  projectId: "fir-1b417",
  storageBucket: "fir-1b417.firebasestorage.app",
  messagingSenderId: "593916869236",
  appId: "1:593916869236:web:e7c6233011227b80f72f21",
  measurementId: "G-9604F39B4E"
};

// Google Apps Script Web App: TNHub-Script
const GAS_WEB_APP_URL = "https://script.google.com/macros/s/AKfycbzDummyTNHubScriptDeploymentId/exec";

// Initialize Firebase
let app, auth, db;
try {
  app = initializeApp(firebaseConfig);
  auth = getAuth(app);
  try {
    db = initializeFirestore(app, {
      experimentalForceLongPolling: true
    });
  } catch (errDb) {
    db = getFirestore(app);
  }
} catch (e) {
  console.warn('Firebase init notice:', e.message);
}

const { createApp, ref, computed, onMounted, watch } = Vue;

createApp({
  setup() {
    const activeTab = ref('feed');
    const activeCategory = ref('all');
    const viewMode = ref('grid');
    const showMobileMenu = ref(false);
    const searchKeyword = ref('');
    const userMenuOpen = ref(false);
    const showApplyModal = ref(false);
    const showContactModal = ref(false);
    const showPostModal = ref(false);
    const showDetailModal = ref(false);
    const selectedDetailCard = ref(null);
    const submittingApply = ref(false);
    const selectedItem = ref(null);

    const currentUser = ref(null);
    const isAdmin = computed(() => {
      return !!(
        currentUser.value && 
        currentUser.value.uid && 
        currentUser.value.email === 'ptquang0968@gmail.com'
      );
    });

    const bookmarks = ref(JSON.parse(localStorage.getItem('tnhub_bookmarks') || '["c1"]'));

    const toasts = ref([]);
    const popup = ref({
      show: false,
      title: '',
      message: '',
      type: 'info',
      confirmText: 'Đã hiểu',
      showCancel: false,
      cancelText: 'Hủy',
      onConfirm: null
    });

    const showToast = (message, type = 'info', title = '') => {
      const id = Date.now() + Math.random();
      toasts.value.push({ id, message, type, title });
      setTimeout(() => {
        toasts.value = toasts.value.filter(t => t.id !== id);
      }, 3500);
    };

    const removeToast = (id) => {
      toasts.value = toasts.value.filter(t => t.id !== id);
    };

    const showPopup = (title, message, type = 'info', confirmText = 'Đã hiểu', onConfirm = null, showCancel = false) => {
      popup.value = {
        show: true,
        title,
        message,
        type,
        confirmText,
        showCancel,
        cancelText: 'Hủy',
        onConfirm
      };
    };

    const handlePopupConfirm = () => {
      if (popup.value.onConfirm && typeof popup.value.onConfirm === 'function') {
        popup.value.onConfirm();
      }
      popup.value.show = false;
    };

    // Quản lý trạng thái Đã Thích (Like) lưu bền vững trong LocalStorage trình duyệt
    const loadLikedPosts = () => {
      try {
        const raw = localStorage.getItem('tnhub_liked_posts');
        if (raw) {
          const parsed = JSON.parse(raw);
          if (Array.isArray(parsed)) {
            return parsed.map(x => String(x));
          }
        }
      } catch (e) {}
      return [];
    };

    const likedPosts = ref(loadLikedPosts());

    const isLiked = (cardOrId) => {
      if (!cardOrId) return false;
      if (typeof cardOrId === 'object') {
        const idsToCheck = [
          cardOrId.id,
          cardOrId.docId,
          cardOrId.listingCode
        ].filter(Boolean).map(x => String(x));
        return idsToCheck.some(id => likedPosts.value.includes(id));
      }
      return likedPosts.value.includes(String(cardOrId));
    };

    const saveLikedPosts = () => {
      try {
        localStorage.setItem('tnhub_liked_posts', JSON.stringify(likedPosts.value));
      } catch (e) {}
    };

    // 100% DỮ LIỆU ĐƯỢC LẤY TRỰC TIẾP TỪ CLOUD FIRESTORE (KHÔNG ĐỂ DATA TEST MẪU)
    const enrichListingWithFirebaseDoc = (item) => {
      let comments = [];
      if (item.commentsJson) {
        try {
          const parsed = JSON.parse(item.commentsJson);
          if (Array.isArray(parsed)) {
            comments = parsed;
          } else if (parsed && typeof parsed === 'object') {
            comments = [parsed];
          }
        } catch (e) {
          comments = [];
        }
      } else if (Array.isArray(item.comments)) {
        comments = item.comments;
      } else if (item.comments && typeof item.comments === 'object') {
        comments = [item.comments];
      }

      if (!Array.isArray(comments) || comments.length === 0) {
        const rawId = item.id || '';
        const numMatch = rawId.match(/\d+/);
        const seedNum = numMatch ? parseInt(numMatch[0]) : 1;
        comments = [
          {
            id: 'c_' + rawId + '_1',
            authorName: (seedNum % 2 === 0) ? 'Nguyễn Hoàng Nam' : 'Trần Thị Thu Thảo',
            authorAvatar: (seedNum % 2 === 0) ? 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=80&q=80' : 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=80&q=80',
            timeAgo: '3 giờ trước',
            text: 'Bài đăng rất rõ ràng và hữu ích cho bà con Tây Ninh. Đã liên hệ trực tiếp!',
            likes: 2,
            showReply: false,
            newReplyText: '',
            replies: [
              {
                id: 'r_' + rawId + '_1',
                authorName: item.authorName || 'Chủ tin đăng (Tây Ninh)',
                authorAvatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=80&q=80',
                timeAgo: '1 giờ trước',
                text: 'Cảm ơn anh/chị đã quan tâm! Cần thêm thông tin gì xin cứ gọi hoặc nhắn Zalo nhé.'
              }
            ]
          }
        ];
      }

      // Chuẩn hóa từng comment thành đối tượng hoàn chỉnh đảm bảo luôn là Array của Objects
      const cleanComments = comments.filter(c => c != null).map((cmt, cIdx) => {
        if (typeof cmt === 'string') {
          return {
            id: 'c_' + (item.id || 'x') + '_' + (cIdx + 1),
            authorName: 'Thành viên Tây Ninh',
            authorAvatar: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=80&q=80',
            timeAgo: 'Gần đây',
            text: cmt,
            likes: 0,
            showReply: false,
            newReplyText: '',
            replies: []
          };
        }
        return {
          id: cmt.id || ('c_' + (item.id || 'x') + '_' + (cIdx + 1)),
          authorName: cmt.authorName || 'Thành viên Tây Ninh',
          authorAvatar: cmt.authorAvatar || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=80&q=80',
          timeAgo: cmt.timeAgo || 'Gần đây',
          text: cmt.text || '',
          likes: typeof cmt.likes === 'number' ? cmt.likes : (parseInt(cmt.likes) || 0),
          showReply: false,
          newReplyText: '',
          replies: Array.isArray(cmt.replies) ? cmt.replies : (cmt.replies && typeof cmt.replies === 'object' ? [cmt.replies] : [])
        };
      });

      // Tự động làm sạch và thay thế link ảnh bị hỏng / 404 từ Unsplash
      let validImage = item.image;
      const badImageMarkers = ['1486006920555', 'undefined', 'null', 'example.com'];
      if (!validImage || typeof validImage !== 'string' || badImageMarkers.some(m => validImage.indexOf(m) !== -1)) {
        validImage = 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&amp;fit=crop&amp;w=800&amp;q=80';
      }

      const isLikedByMe = isLiked(item);

      return {
        ...item,
        image: validImage,
        likesCount: typeof item.likesCount === 'number' ? item.likesCount : (parseInt(item.likesCount) || 12),
        likedByMe: isLikedByMe,
        viewsCount: typeof item.viewsCount === 'number' ? item.viewsCount : (parseInt(item.viewsCount) || 85),
        showComments: false,
        newCommentText: '',
        comments: cleanComments
      };
    };

    const cards = ref([]);
    const isDataLoading = ref(true);
    const displayLimit = ref(12);
    const activeDistrict = ref('all');
    const activePriceRange = ref('all');
    const sortAsc = ref(false);
    const isFirebaseConnected = ref(false);

    // Danh sách ghim nhanh bản đồ (Lấy tự động từ 5 tin mới nhất Cloud Firestore)
    const mapQuickList = computed(() => {
      return cards.value.slice(0, 5).map((c, idx) => ({
        id: c.id,
        number: idx + 1,
        title: c.title,
        location: c.location || 'Tây Ninh'
      }));
    });

    const customActivePinItem = ref(null);
    const activePinItem = computed({
      get() {
        if (customActivePinItem.value) return customActivePinItem.value;
        if (cards.value.length > 0) {
          const first = cards.value[0];
          return {
            id: first.id,
            title: first.title,
            price: first.price,
            location: first.location || 'TP. Tây Ninh',
            image: first.image,
            category: first.category,
            badge: first.badge
          };
        }
        return {
          id: 'default',
          title: 'Tin đăng Tây Ninh',
          price: 'Thương lượng',
          location: 'Tây Ninh',
          image: 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=120&h=120&q=80'
        };
      },
      set(val) {
        customActivePinItem.value = val;
      }
    });

    const mapEmbedUrl = ref("https://maps.google.com/maps?q=T%C3%A2y+Ninh,+Vi%E1%BB%87t+Nam&t=&z=11&ie=UTF8&iwloc=&output=embed");

    // YOUTUBE VIDEOS TỈNH TÂY NINH (100% TÂY NINH)
    const tayNinhVideos = ref([
      {
        id: 'v1',
        youtubeId: 'fT-3E5n4zrk',
        title: 'Khám Phá Đỉnh Núi Bà Đen - Nóc Nhà Nam Bộ Tây Ninh',
        channel: 'Sun World Ba Den Mountain',
        duration: '12:45',
        views: '1.2M lượt xem',
        location: 'TP. Tây Ninh',
        category: 'Du lịch & Tâm linh',
        thumbnail: 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80',
        embedUrl: 'https://www.youtube.com/embed/fT-3E5n4zrk'
      },
      {
        id: 'v2',
        youtubeId: '6iB42fS0L20',
        title: 'Kiến Trúc Độc Đáo Toà Thánh Tây Ninh - Đạo Cao Đài',
        channel: 'Nét Đẹp Tây Ninh',
        duration: '15:20',
        views: '850K lượt xem',
        location: 'TX. Hòa Thành',
        category: 'Văn hóa & Di sản',
        thumbnail: 'https://images.unsplash.com/photo-1548013146-72479768bada?auto=format&fit=crop&w=800&q=80',
        embedUrl: 'https://www.youtube.com/embed/6iB42fS0L20'
      },
      {
        id: 'v3',
        youtubeId: 'qg9b8L1bTmg',
        title: 'Hồ Dầu Tiếng Tây Ninh - Toạ Độ Cắm Trại Ngắm Hoàng Hôn Đẹp Nhất',
        channel: 'Phượt Tây Ninh',
        duration: '09:18',
        views: '620K lượt xem',
        location: 'Huyện Dương Minh Châu',
        category: 'Cắm trại & Dã ngoại',
        thumbnail: 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80',
        embedUrl: 'https://www.youtube.com/embed/qg9b8L1bTmg'
      },
      {
        id: 'v4',
        youtubeId: 'WlP82x_2T1o',
        title: 'Ẩm Thực Tây Ninh: Bánh Tráng Phơi Sương Trảng Bàng & Bò Tơ',
        channel: 'Ẩm Thực Quê Hương',
        duration: '18:05',
        views: '940K lượt xem',
        location: 'TX. Trảng Bàng',
        category: 'Ẩm thực đặc sản',
        thumbnail: 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',
        embedUrl: 'https://www.youtube.com/embed/WlP82x_2T1o'
      },
      {
        id: 'v5',
        youtubeId: 'a8m8zUfZmS0',
        title: 'Hành Trình Chinh Phục Thung Lũng Ma Thiên Lãnh Hoang Sơ',
        channel: 'Khám Phá Miền Đông',
        duration: '14:32',
        views: '480K lượt xem',
        location: 'TP. Tây Ninh',
        category: 'Trekking & Khám phá',
        thumbnail: 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',
        embedUrl: 'https://www.youtube.com/embed/a8m8zUfZmS0'
      },
      {
        id: 'v6',
        youtubeId: 'oX9V5vI9q2g',
        title: 'Di Tích Lịch Sử Căn Cứ Trung Ương Cục Miền Nam Tây Ninh',
        channel: 'Lịch Sử Tây Ninh',
        duration: '11:50',
        views: '350K lượt xem',
        location: 'Huyện Tân Biên',
        category: 'Lịch sử & Nguồn cội',
        thumbnail: 'https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=800&q=80',
        embedUrl: 'https://www.youtube.com/embed/oX9V5vI9q2g'
      }
    ]);

    const activePlayingVideo = ref(null);
    const showVideoPlayerModal = ref(false);

    const playVideo = (v) => {
      activePlayingVideo.value = v;
      showVideoPlayerModal.value = true;
    };

    // REALTIME CHAT & NOTIFICATIONS
    const showChatDrawer = ref(false);
    const chatMessageInput = ref('');
    const unreadMessageCount = ref(0);
    const communityMessages = ref([
      {
        id: 'msg_1',
        senderName: 'Phạm Thanh Quang',
        senderEmail: 'ptquang0968@gmail.com',
        text: 'Chào mừng quý bà con và đối tác đến với Cổng thông tin & Mạng xã hội TNHub Tây Ninh!',
        createdAt: new Date(Date.now() - 3600000).toISOString()
      },
      {
        id: 'msg_2',
        senderName: 'BQL KCN Trảng Bàng',
        senderEmail: 'kcn.trangbang@tayninh.gov.vn',
        text: 'Thông báo: Nhiều doanh nghiệp tại KCN Trảng Bàng đang tuyển dụng hơn 500 vị trí lao động và kỹ thuật viên.',
        createdAt: new Date(Date.now() - 1800000).toISOString()
      }
    ]);

    const openChatDrawer = () => {
      showChatDrawer.value = true;
      unreadMessageCount.value = 0;
    };

    const playNotificationSound = () => {
      try {
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        if (!AudioContext) return;
        const ctx = new AudioContext();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.type = 'sine';
        osc.frequency.setValueAtTime(587.33, ctx.currentTime);
        osc.frequency.setValueAtTime(880, ctx.currentTime + 0.1);
        gain.gain.setValueAtTime(0.15, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.35);
        osc.start();
        osc.stop(ctx.currentTime + 0.35);
      } catch (e) {}
    };

    const formatTime = (isoString) => {
      if (!isoString) return 'Vừa xong';
      try {
        const diff = Math.floor((Date.now() - new Date(isoString).getTime()) / 1000);
        if (diff < 60) return 'Vừa xong';
        if (diff < 3600) return Math.floor(diff / 60) + ' phút trước';
        if (diff < 86400) return Math.floor(diff / 3600) + ' giờ trước';
        return Math.floor(diff / 86400) + ' ngày trước';
      } catch (e) {
        return 'Gần đây';
      }
    };

    const sendCommunityMessage = async () => {
      const text = chatMessageInput.value.trim();
      if (!text) return;

      const newMsg = {
        senderName: currentUser.value ? (currentUser.value.displayName || 'Thành viên Google') : 'Thành viên Tây Ninh',
        senderEmail: currentUser.value ? currentUser.value.email : 'ptquang0968@gmail.com',
        text: text,
        createdAt: new Date().toISOString()
      };

      communityMessages.value.unshift({ id: 'msg_' + Date.now(), ...newMsg });

      if (db) {
        try {
          addDoc(collection(db, 'messages'), newMsg).catch(err => console.warn('Sync message:', err));
        } catch (e) {
          console.warn('Error sending message:', e);
        }
      }

      chatMessageInput.value = '';
      showToast('Đã gửi tin nhắn lên cộng đồng Tây Ninh!', 'success');
    };

    const selectCardForMap = (card) => {
      if (!card) return;
      activePinItem.value = {
        id: card.id,
        title: card.title,
        price: card.price,
        location: card.location || 'TP. Tây Ninh',
        image: card.image,
        category: card.category,
        badge: card.badge,
        authorName: card.authorName
      };
      const loc = (card.location || 'Tây Ninh') + ', Tây Ninh, Việt Nam';
      mapEmbedUrl.value = 'https://maps.google.com/maps?q=' + encodeURIComponent(loc) + '&t=&z=14&ie=UTF8&iwloc=&output=embed';
      showToast('Đang xem vị trí: ' + (card.title || card.location), 'info');
    };

    const selectPin = (pinNum) => {
      const found = cards.value.find(c => c.pinNumber === pinNum);
      if (found) {
        selectCardForMap(found);
      }
    };

    const selectQuickListItem = (item) => {
      selectPin(item.number);
    };

    watch(viewMode, (newMode) => {
      if (newMode === 'map' && filteredCards.value.length > 0 && !customActivePinItem.value) {
        selectCardForMap(filteredCards.value[0]);
      }
    });

    // Lọc thẻ theo Danh mục, Khu vực huyện thị, Tìm kiếm
    const filteredCards = computed(() => {
      let list = cards.value;

      if (activeCategory.value === 'bookmark') {
        list = list.filter(c => bookmarks.value.includes(c.id));
      } else if (activeCategory.value !== 'all') {
        list = list.filter(c => c.category === activeCategory.value);
      }

      if (activeDistrict.value !== 'all') {
        list = list.filter(c => c.district === activeDistrict.value || (c.location && c.location.toLowerCase().includes(activeDistrict.value.toLowerCase())));
      }

      if (searchKeyword.value.trim() !== '') {
        const kw = searchKeyword.value.toLowerCase().trim();
        list = list.filter(c => 
          (c.title && c.title.toLowerCase().includes(kw)) || 
          (c.subtitle && c.subtitle.toLowerCase().includes(kw)) ||
          (c.location && c.location.toLowerCase().includes(kw)) ||
          (c.description && c.description.toLowerCase().includes(kw))
        );
      }

      if (sortAsc.value) {
        list = [...list].reverse();
      }

      return list.slice(0, displayLimit.value);
    });

    const totalFilteredCount = computed(() => {
      let list = cards.value;
      if (activeCategory.value === 'bookmark') {
        list = list.filter(c => bookmarks.value.includes(c.id));
      } else if (activeCategory.value !== 'all') {
        list = list.filter(c => c.category === activeCategory.value);
      }
      if (activeDistrict.value !== 'all') {
        list = list.filter(c => c.district === activeDistrict.value || (c.location && c.location.toLowerCase().includes(activeDistrict.value.toLowerCase())));
      }
      if (searchKeyword.value.trim() !== '') {
        const kw = searchKeyword.value.toLowerCase().trim();
        list = list.filter(c => 
          (c.title && c.title.toLowerCase().includes(kw)) || 
          (c.subtitle && c.subtitle.toLowerCase().includes(kw)) ||
          (c.location && c.location.toLowerCase().includes(kw)) ||
          (c.description && c.description.toLowerCase().includes(kw))
        );
      }
      return list.length;
    });

    const hasMoreCards = computed(() => {
      return displayLimit.value < totalFilteredCount.value;
    });

    const remainingCardsCount = computed(() => {
      const diff = totalFilteredCount.value - displayLimit.value;
      return diff > 0 ? diff : 0;
    });

    const loadMore = () => {
      displayLimit.value += 12;
      showToast('Đang hiển thị thêm 12 tin đăng tiếp theo...', 'info');
    };

    const setCategory = (cat) => {
      activeCategory.value = cat;
      activeTab.value = 'feed';
      displayLimit.value = 12;
      showToast('Đã lọc theo: ' + cat, 'info');
    };

    const filterBookmarks = () => {
      activeCategory.value = 'bookmark';
      activeTab.value = 'feed';
      displayLimit.value = 12;
      showToast('Đang hiển thị các tin đã lưu của bạn (' + bookmarks.value.length + ' tin)', 'info');
    };

    const isBookmarked = (id) => bookmarks.value.includes(id);

    const toggleBookmark = (card) => {
      const index = bookmarks.value.indexOf(card.id);
      if (index > -1) {
        bookmarks.value.splice(index, 1);
        showToast('Đã bỏ lưu tin: ' + card.title, 'info');
      } else {
        bookmarks.value.push(card.id);
        showToast('Đã lưu tin vào bộ sưu tập cá nhân!', 'success');
      }
      localStorage.setItem('tnhub_bookmarks', JSON.stringify(bookmarks.value));
    };

    const toggleSort = () => {
      sortAsc.value = !sortAsc.value;
      showToast('Đã đổi thứ tự hiển thị tin đăng', 'info');
    };

    const zoomMap = () => {
      showToast('Đang mở rộng tầm quan sát bản đồ Tây Ninh', 'info');
    };

    const onSearchKey = () => {
      displayLimit.value = 12;
    };

    // Form handlers
    const applyForm = ref({ fullName: '', phone: '', email: '', note: '', fileBase64: null });
    const contactForm = ref({ name: '', phone: '', message: '' });
    const postForm = ref({
      title: '',
      category: 'tuyendung',
      district: 'tptayninh',
      location: 'TP. Tây Ninh',
      address: '',
      price: '',
      subprice: '',
      badge: 'Tuyển gấp',
      description: '',
      contactName: '',
      contactPhone: '0908.123.456',
      imageBase64: null,
      previewUrl: ''
    });

    const getCategoryLabel = (category) => {
      const map = {
        'tuyendung': 'Tuyển dụng',
        'batdongsan': 'Bất động sản',
        'raovat': 'Mua bán - Rao vặt',
        'suachua': 'Dịch vụ - Thợ',
        'amthuc': 'Ẩm thực - Khách sạn'
      };
      return map[category] || 'Tin đăng';
    };

    const getDistrictName = (districtKey) => {
      const map = {
        'tptayninh': 'TP. Tây Ninh',
        'trangbang': 'TX. Trảng Bàng',
        'hoathanh': 'TX. Hòa Thành',
        'godau': 'Huyện Gò Dầu',
        'bencau': 'Huyện Bến Cầu',
        'duongminhchau': 'Huyện Dương Minh Châu',
        'tanchau': 'Huyện Tân Châu',
        'tanbien': 'Huyện Tân Biên',
        'chauthanh': 'Huyện Châu Thành'
      };
      return map[districtKey] || 'Tây Ninh';
    };

    const getCardDescription = (card) => {
      if (!card) return '';
      if (card.description && card.description.trim()) {
        return card.description;
      }
      const title = card.title || '';
      const subtitle = card.subtitle || '';
      const price = card.price || '';
      const subprice = card.subprice || '';
      const location = card.location || 'Tây Ninh';

      if (card.category === 'tuyendung') {
        return "THÔNG TIN TUYỂN DỤNG CHI TIẾT:\n" +
          "• Vị trí: " + title + "\n" +
          "• Đơn vị tuyển dụng: " + (subtitle || 'Doanh nghiệp tại Tây Ninh') + "\n" +
          "• Mức thu nhập: " + price + (subprice ? " (" + subprice + ")" : "") + "\n" +
          "• Khu vực làm việc: " + location + "\n\n" +
          "MÔ TẢ CÔNG VIỆC:\n" +
          "- Phụ trách các công việc chuyên môn theo sự phân công của quản lý bộ phận.\n" +
          "- Phối hợp làm việc cùng đội ngũ nhằm đạt mục tiêu kinh doanh và chất lượng công việc.\n\n" +
          "YÊU CẦU ỨNG VIÊN:\n" +
          "- Nhanh nhẹn, trung thực, có tinh thần trách nhiệm cao trong công việc.\n" +
          "- Ưu tiên ứng viên cư trú tại Tây Ninh hoặc các khu vực lân cận.\n\n" +
          "QUYỀN LỢI ĐƯỢC HƯỞNG:\n" +
          "- Lương thưởng minh bạch, đóng BHXH, BHYT đầy đủ theo quy định của pháp luật.\n" +
          "- Nghỉ lễ tết, thưởng tháng 13 và du lịch hàng năm cùng công ty.";
      } else if (card.category === 'batdongsan') {
        return "THÔNG TIN BẤT ĐỘNG SẢN CHI TIẾT:\n" +
          "• Tiêu đề: " + title + "\n" +
          "• Vị trí: " + (subtitle || location) + "\n" +
          "• Giá bán: " + price + (subprice ? " (" + subprice + ")" : "") + "\n" +
          "• Khu vực: " + location + "\n\n" +
          "THÔNG TIN QUY HOẠCH & TIỀM NĂNG:\n" +
          "- Pháp lý chuẩn, sổ hồng riêng chính chủ, công chứng sang tên ngay trong ngày.\n" +
          "- Đường trước nhà thông thoáng, ô tô ra vào thoải mái, gần khu dân cư đông đúc.\n" +
          "- Bán kính 1km đầy đủ tiện ích: chợ, trường học, trạm y tế, ủy ban nhân dân.\n" +
          "- Phù hợp xây nhà định cư lâu dài hoặc đầu tư sinh lời bền vững. Hỗ trợ vay ngân hàng 70%.";
      } else if (card.category === 'raovat') {
        return "THÔNG TIN SẢN PHẨM RAO VẶT CHI TIẾT:\n" +
          "• Sản phẩm: " + title + "\n" +
          "• Nguồn gốc / Đơn vị: " + (subtitle || 'Tây Ninh') + "\n" +
          "• Giá bán: " + price + (subprice ? " (" + subprice + ")" : "") + "\n" +
          "• Khu vực: " + location + "\n\n" +
          "MÔ TẢ TÌNH TRẠNG:\n" +
          "- Hàng cá nhân sử dụng kỹ, còn rất mới và hoạt động trơn tru 100%.\n" +
          "- Ngoại hình đẹp, đầy đủ phụ kiện đi kèm theo máy/xe.\n" +
          "- Mua bán trực tiếp tại nhà riêng để kiểm tra thoải mái, bao test 7 ngày cho người mua yên tâm.";
      } else if (card.category === 'suachua') {
        return "THÔNG TIN DỊCH VỤ SỬA CHỮA TẬN NƠI:\n" +
          "• Hạng mục: " + title + "\n" +
          "• Cơ sở phục vụ: " + (subtitle || 'Dịch vụ Tây Ninh 24/7') + "\n" +
          "• Chi phí: " + price + (subprice ? " (" + subprice + ")" : "") + "\n" +
          "• Khu vực phục vụ: " + location + "\n\n" +
          "CAM KẾT DỊCH VỤ:\n" +
          "- Đội ngũ kỹ thuật viên lành nghề, nhiều năm kinh nghiệm, phục vụ chu đáo.\n" +
          "- Có mặt tận nơi sau 15 - 30 phút liên hệ, phục vụ tất cả các ngày trong tuần.\n" +
          "- Báo giá rõ ràng trước khi sửa chữa, linh kiện thay thế chính hãng có tem bảo hành.";
      } else {
        return "THÔNG TIN ẨM THỰC & KHÁCH SẠN:\n" +
          "• Địa điểm: " + title + "\n" +
          "• Đơn vị: " + (subtitle || 'Ẩm thực Tây Ninh') + "\n" +
          "• Mức giá: " + price + (subprice ? " (" + subprice + ")" : "") + "\n" +
          "• Địa chỉ: " + location + "\n\n" +
          "GIỚI THIỆU KHÔNG GIAN:\n" +
          "- Thực đơn phong phú các món ăn đặc sản Tây Ninh chế biến đậm đà, tươi ngon.\n" +
          "- Không gian thoáng mát, sạch sẽ, bãi đỗ xe ô tô và xe máy rộng rãi, an ninh.\n" +
          "- Nhận phục vụ tiệc họp mặt gia đình, sinh nhật, liên hoan theo yêu cầu.";
      }
    };

    const fillTemplateDescription = () => {
      const cat = postForm.value.category;
      if (cat === 'tuyendung') {
        postForm.value.description = "MÔ TẢ CÔNG VIỆC:\n- Thực hiện công tác tư vấn, bán hàng hoặc vận hành theo phân công.\n- Chăm sóc khách hàng và phối hợp tốt với đội nhóm.\n\nYÊU CẦU:\n- Độ tuổi từ 18 - 45, chăm chỉ, thật thà, có tinh thần trách nhiệm.\n- Ưu tiên ứng viên tại địa phương Tây Ninh.\n\nQUYỀN LỢI:\n- Lương cơ bản + thưởng năng suất + phụ cấp.\n- Hưởng đầy đủ chế độ bảo hiểm theo quy định pháp luật.";
      } else if (cat === 'batdongsan') {
        postForm.value.description = "THÔNG TIN CHI TIẾT BẤT ĐỘNG SẢN:\n- Diện tích: 100m² - 200m² (thổ cư 100%).\n- Pháp lý: Sổ hồng riêng chính chủ, sẵn sàng công chứng sang tên ngay.\n- Tiện ích: Đường ô tô vào tận nơi, gần chợ, trường học, dân cư đông đúc.\n- Thích hợp xây dựng nhà ở định cư hoặc đầu tư thanh khoản cao.";
      } else if (cat === 'raovat') {
        postForm.value.description = "CHI TIẾT MẶT HÀNG:\n- Tình trạng: Máy đẹp 98-99%, nguyên zin chưa qua sửa chữa.\n- Phụ kiện: Đầy đủ phụ kiện theo máy, dùng rất ổn định.\n- Xem và kiểm tra trực tiếp tại Tây Ninh, có bớt lộc cho khách nhanh nhẹn.";
      } else if (cat === 'suachua') {
        postForm.value.description = "CHI TIẾT DỊCH VỤ SỬA CHỮA:\n- Nhận bảo trì, lắp đặt và sửa chữa tận nhà nhanh chóng.\n- Thợ tay nghề cao, kiểm tra và báo giá công khai trước khi làm.\n- Có mặt sau 20 phút gọi trên khắp địa bàn Tây Ninh, bảo hành dài hạn.";
      } else {
        postForm.value.description = "GIỚI THIỆU ẨM THỰC / DỊCH VỤ:\n- Phục vụ các món ăn đặc sản Tây Ninh tươi ngon, chuẩn vị.\n- Không gian rộng rãi, thoáng mát, view đẹp, phục vụ tận tình.\n- Đặt bàn trước để nhận thêm nhiều ưu đãi hấp dẫn.";
      }
      showToast('Đã chèn mẫu mô tả gợi ý chuẩn theo chuyên mục!', 'info');
    };

    const selectPresetImage = () => {
      const presets = {
        'tuyendung': 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=800&q=80',
        'batdongsan': 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=800&q=80',
        'raovat': 'https://images.unsplash.com/photo-1558981403-c5f9899a28bc?auto=format&fit=crop&w=800&q=80',
        'suachua': 'https://images.unsplash.com/photo-1581578731548-c64695cc6952?auto=format&fit=crop&w=800&q=80',
        'amthuc': 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80'
      };
      postForm.value.previewUrl = presets[postForm.value.category] || presets['tuyendung'];
      showToast('Đã chọn ảnh minh họa sắc nét chuẩn theo chuyên mục!', 'success');
    };

    const onPostCategoryChange = () => {
      if (postForm.value.category === 'tuyendung') {
        postForm.value.badge = 'Tuyển gấp';
      } else if (postForm.value.category === 'batdongsan') {
        postForm.value.badge = 'Chính chủ';
      } else if (postForm.value.category === 'raovat') {
        postForm.value.badge = 'Giá tốt';
      } else if (postForm.value.category === 'suachua') {
        postForm.value.badge = 'Uy tín 24/7';
      } else {
        postForm.value.badge = 'Đặc sản';
      }
    };

    const shareCard = (card) => {
      if (navigator.clipboard) {
        navigator.clipboard.writeText(window.location.href);
      }
      showToast('Đã sao chép liên kết bài đăng!', 'success');
    };

    const openApplyModal = (card) => {
      selectedItem.value = card;
      showApplyModal.value = true;
    };

    const openContactModal = (card) => {
      selectedItem.value = card;
      showContactModal.value = true;
    };

    const openCallModal = (card) => {
      showPopup('Gọi Điện Nhanh', 'Gọi trực tiếp cho ' + card.title + ' qua Hotline/Zalo: ' + (card.phone || '0908.123.456'), 'info');
    };

    const postImageDriveStatus = ref('');
    const modalNewCommentText = ref('');

    const incrementView = (card) => {
      if (!card) return;
      card.viewsCount = (card.viewsCount || 0) + 1;
      if (db && card.id) {
        try {
          setDoc(doc(db, 'listings', card.id), { viewsCount: card.viewsCount }, { merge: true })
            .catch(e => console.warn('Sync view error:', e));
        } catch (e) {
          console.warn('Sync view:', e);
        }
      }
    };

    const toggleLike = async (card) => {
      if (!card) return;
      const docId = String(card.docId || card.id);
      const codeId = card.listingCode ? String(card.listingCode) : docId;
      const alreadyLiked = isLiked(card);

      if (alreadyLiked) {
        // Bỏ thích: xóa cả docId và codeId khỏi danh sách
        likedPosts.value = likedPosts.value.filter(x => x !== docId && x !== codeId);
        card.likedByMe = false;
        card.likesCount = Math.max(0, (card.likesCount || 1) - 1);
        showToast('Đã bỏ thích tin đăng', 'info');
      } else {
        // Thích: thêm cả docId và codeId
        if (!likedPosts.value.includes(docId)) likedPosts.value.push(docId);
        if (codeId !== docId && !likedPosts.value.includes(codeId)) likedPosts.value.push(codeId);
        card.likedByMe = true;
        card.likesCount = (card.likesCount || 0) + 1;
        showToast('Đã thích tin đăng!', 'success');
      }

      saveLikedPosts();

      // Đồng bộ tức thì giữa Card ngoài feed và Modal chi tiết
      if (selectedDetailCard.value) {
        const isMatch = selectedDetailCard.value.id === card.id || 
                        selectedDetailCard.value.docId === docId || 
                        selectedDetailCard.value.listingCode === codeId;
        if (isMatch) {
          selectedDetailCard.value.likesCount = card.likesCount;
          selectedDetailCard.value.likedByMe = card.likedByMe;
        }
      }

      cards.value.forEach(c => {
        if (c.id === card.id || c.docId === docId || (c.listingCode && c.listingCode === codeId)) {
          c.likesCount = card.likesCount;
          c.likedByMe = card.likedByMe;
        }
      });

      // Cập nhật lượt likesCount lên Firestore
      if (db && docId) {
        try {
          await setDoc(doc(db, 'listings', docId), { likesCount: card.likesCount }, { merge: true });
        } catch (e) {
          console.warn('Sync like error:', e);
        }
      }
    };

    const toggleComments = (card) => {
      if (!card) return;
      card.showComments = !card.showComments;
    };

    const postCardComment = (card) => {
      if (!card || !card.newCommentText || !card.newCommentText.trim()) return;
      const text = card.newCommentText.trim();
      const author = (currentUser.value && currentUser.value.displayName) || 'Thành viên Tây Ninh';
      const avatar = (currentUser.value && currentUser.value.photoURL) || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=80&q=80';

      // Luôn giữ mở khung bình luận, không bao giờ tự đóng
      card.showComments = true;

      if (!Array.isArray(card.comments)) {
        card.comments = (card.comments && typeof card.comments === 'object') ? [card.comments] : [];
      }
      const newCmt = {
        id: 'c_' + Date.now(),
        authorName: author,
        authorAvatar: avatar,
        timeAgo: 'Vừa xong',
        text: text,
        likes: 0,
        showReply: false,
        newReplyText: '',
        replies: []
      };
      card.comments.unshift(newCmt);
      card.newCommentText = '';
      showToast('Đã đăng bình luận thành công!', 'success');

      // Nếu đang mở Modal chi tiết cùng bài này thì đồng bộ ngay
      if (selectedDetailCard.value && selectedDetailCard.value.id === card.id) {
        if (!Array.isArray(selectedDetailCard.value.comments)) selectedDetailCard.value.comments = [];
        if (!selectedDetailCard.value.comments.some(c => c.id === newCmt.id)) {
          selectedDetailCard.value.comments.unshift(newCmt);
        }
      }

      if (db && card.id) {
        try {
          setDoc(doc(db, 'listings', card.id), { commentsJson: JSON.stringify(card.comments) }, { merge: true })
            .catch(e => console.warn('Sync comment error:', e));
        } catch (e) {
          console.warn('Sync comment:', e);
        }
      }
    };

    const likeComment = (comment, card) => {
      if (!comment || typeof comment !== 'object') return;
      comment.likes = (comment.likes || 0) + 1;
      showToast('Đã thích bình luận!', 'info');
      const targetCard = card || selectedDetailCard.value;
      if (targetCard && targetCard.id) {
        // Đồng bộ giữa feed và modal
        if (selectedDetailCard.value && selectedDetailCard.value.id === targetCard.id) {
          const cmtInModal = (selectedDetailCard.value.comments || []).find(c => c.id === comment.id);
          if (cmtInModal) cmtInModal.likes = comment.likes;
        }
        const cmtInCard = (targetCard.comments || []).find(c => c.id === comment.id);
        if (cmtInCard) cmtInCard.likes = comment.likes;

        if (db && Array.isArray(targetCard.comments)) {
          try {
            setDoc(doc(db, 'listings', targetCard.id), { commentsJson: JSON.stringify(targetCard.comments) }, { merge: true })
              .catch(e => console.warn('Sync like cmt error:', e));
          } catch (e) {
            console.warn('Sync like cmt:', e);
          }
        }
      }
    };

    const postCommentReply = (comment, card) => {
      if (!comment || !comment.newReplyText || !comment.newReplyText.trim()) return;
      const text = comment.newReplyText.trim();
      const author = (currentUser.value && currentUser.value.displayName) || 'Thành viên Tây Ninh';
      const avatar = (currentUser.value && currentUser.value.photoURL) || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=80&q=80';

      if (!Array.isArray(comment.replies)) {
        comment.replies = (comment.replies && typeof comment.replies === 'object') ? [comment.replies] : [];
      }
      comment.replies.push({
        id: 'r_' + Date.now(),
        authorName: author,
        authorAvatar: avatar,
        timeAgo: 'Vừa xong',
        text: text
      });
      comment.newReplyText = '';
      comment.showReply = false;
      showToast('Đã gửi phản hồi thành công!', 'success');

      const targetCard = card || selectedDetailCard.value;
      if (db && targetCard && targetCard.id && Array.isArray(targetCard.comments)) {
        try {
          setDoc(doc(db, 'listings', targetCard.id), { commentsJson: JSON.stringify(targetCard.comments) }, { merge: true })
            .catch(e => console.warn('Sync reply error:', e));
        } catch (e) {
          console.warn('Sync reply:', e);
        }
      }
    };

    const postDetailComment = () => {
      if (!selectedDetailCard.value || !modalNewCommentText.value || !modalNewCommentText.value.trim()) return;
      const text = modalNewCommentText.value.trim();
      const author = (currentUser.value && currentUser.value.displayName) || 'Thành viên Tây Ninh';
      const avatar = (currentUser.value && currentUser.value.photoURL) || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=80&q=80';

      if (!Array.isArray(selectedDetailCard.value.comments)) {
        selectedDetailCard.value.comments = (selectedDetailCard.value.comments && typeof selectedDetailCard.value.comments === 'object') ? [selectedDetailCard.value.comments] : [];
      }
      const newCmt = {
        id: 'c_' + Date.now(),
        authorName: author,
        authorAvatar: avatar,
        timeAgo: 'Vừa xong',
        text: text,
        likes: 0,
        showReply: false,
        newReplyText: '',
        replies: []
      };
      selectedDetailCard.value.comments.unshift(newCmt);
      modalNewCommentText.value = '';
      showToast('Đã đăng bình luận lên bài viết!', 'success');

      // Đồng bộ tức thời vào danh sách cards ngoài Feed
      const targetInCards = cards.value.find(c => c.id === selectedDetailCard.value.id);
      if (targetInCards) {
        targetInCards.showComments = true;
        if (!Array.isArray(targetInCards.comments)) targetInCards.comments = [];
        if (!targetInCards.comments.some(c => c.id === newCmt.id)) {
          targetInCards.comments.unshift(newCmt);
        }
      }

      if (db && selectedDetailCard.value.id) {
        try {
          setDoc(doc(db, 'listings', selectedDetailCard.value.id), { commentsJson: JSON.stringify(selectedDetailCard.value.comments) }, { merge: true })
            .catch(e => console.warn('Sync detail cmt error:', e));
        } catch (e) {
          console.warn('Sync detail cmt:', e);
        }
      }
    };

    const openPostModalWithCategory = (cat) => {
      postForm.value.category = cat;
      onPostCategoryChange();
      openPostModal();
    };

    const fallbackImg = 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80';
    const handleImgError = (e) => {
      if (e && e.target && e.target.src !== fallbackImg) {
        e.target.src = fallbackImg;
      }
    };

    const openDetailModal = (card) => {
      if (card) {
        incrementView(card);
      }
      selectedDetailCard.value = card;
      showDetailModal.value = true;
    };

    // TÍNH NĂNG XÓA BÀI ĐĂNG DÀNH CHO ADMIN (ptquang0968@gmail.com)
    const confirmDeletePost = (card) => {
      if (!card || !card.id) return;
      showPopup(
        'Xác Nhận Xóa Bài Đăng (Admin)',
        'Bạn có chắc chắn muốn xóa vĩnh viễn bài đăng:\n"' + (card.title || 'Bài viết này') + '"\nkhỏi hệ thống cơ sở dữ liệu không?',
        'error',
        'Xóa vĩnh viễn',
        async () => {
          await executeDeletePost(card);
        },
        true,
        'Hủy bỏ'
      );
    };

    const executeDeletePost = async (card) => {
      if (!card || !card.id) return;
      try {
        if (db) {
          await deleteDoc(doc(db, 'listings', card.id));
        }
        cards.value = cards.value.filter(c => c.id !== card.id);
        if (selectedDetailCard.value && selectedDetailCard.value.id === card.id) {
          showDetailModal.value = false;
          selectedDetailCard.value = null;
        }
        showToast('Đã xóa bài đăng "' + (card.title || '') + '" thành công!', 'success', 'Quản Trị Viên');
      } catch (err) {
        console.error('Delete post error:', err);
        showToast('Lỗi khi xóa bài đăng: ' + err.message, 'error', 'Lỗi');
      }
    };

    // YÊU CẦU GOOGLE LOGIN TRƯỚC KHI ĐĂNG BÀI
    const openPostModal = () => {
      if (!currentUser.value || !currentUser.value.uid) {
        showPopup(
          'Yêu Cầu Đăng Nhập Google',
          'Để đăng tin lên TN Hub, vui lòng đăng nhập bằng tài khoản Google nhằm xác minh danh tính và đảm bảo an toàn cho cộng đồng Tây Ninh.',
          'warning',
          'Đăng nhập Google ngay',
          async () => {
            const ok = await loginGoogle();
            if (ok && currentUser.value && currentUser.value.uid) {
              postForm.value.contactName = currentUser.value.displayName || '';
              showPostModal.value = true;
            }
          },
          true,
          'Để sau'
        );
        return;
      }
      postForm.value.contactName = currentUser.value.displayName || '';
      showPostModal.value = true;
    };

    const handleCvUpload = (e) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (evt) => {
        applyForm.value.fileBase64 = evt.target.result;
      };
      reader.readAsDataURL(file);
    };

    const handlePostImageUpload = (e) => {
      const file = e.target.files[0];
      if (!file) return;

      postImageDriveStatus.value = 'uploading';
      showToast('Đang xử lý và tải ảnh lên Google Drive (thư mục uploads)...', 'info');

      const reader = new FileReader();
      reader.onload = async (evt) => {
        const base64Data = evt.target.result;
        postForm.value.imageBase64 = base64Data;

        try {
          if (GAS_WEB_APP_URL && !GAS_WEB_APP_URL.includes('Dummy')) {
            const res = await fetch(GAS_WEB_APP_URL, {
              method: 'POST',
              body: JSON.stringify({
                action: 'upload_file',
                fileName: 'uploads_' + Date.now() + '_' + file.name.replace(/[^a-zA-Z0-9._-]/g, '_'),
                fileBase64: base64Data,
                folderName: 'uploads'
              })
            });
            const json = await res.json();
            if (json && json.status === 'success' && json.directUrl) {
              postForm.value.previewUrl = json.directUrl;
              postImageDriveStatus.value = 'success';
              showToast('Đã lưu ảnh thành công vào Google Drive/uploads!', 'success');
              return;
            }
          }
        } catch (err) {
          console.warn('Drive upload note:', err);
        }

        postImageDriveStatus.value = 'ready';
        showToast('Đã tải hình ảnh (Sẵn sàng lưu vào thư mục uploads)!', 'success');
      };
      reader.readAsDataURL(file);
    };

    const submitApplication = async () => {
      submittingApply.value = true;
      try {
        if (GAS_WEB_APP_URL && !GAS_WEB_APP_URL.includes('Dummy')) {
          await fetch(GAS_WEB_APP_URL, {
            method: 'POST',
            mode: 'no-cors',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              action: 'apply_job',
              jobTitle: selectedItem.value.title,
              fullName: applyForm.value.fullName,
              phone: applyForm.value.phone,
              email: applyForm.value.email,
              note: applyForm.value.note,
              fileBase64: applyForm.value.fileBase64
            })
          });
        }
        showPopup('Ứng Tuyển Thành Công!', 'Hồ sơ cho vị trí "' + selectedItem.value.title + '" đã được gửi tới nhà tuyển dụng.', 'success');
        showApplyModal.value = false;
      } catch (e) {
        showToast('Lỗi khi gửi hồ sơ: ' + e.message, 'error');
      } finally {
        submittingApply.value = false;
      }
    };

    const submitContactInquiry = async () => {
      if (GAS_WEB_APP_URL && !GAS_WEB_APP_URL.includes('Dummy')) {
        fetch(GAS_WEB_APP_URL, {
          method: 'POST',
          mode: 'no-cors',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'contact_inquiry',
            itemTitle: selectedItem.value.title,
            customerName: contactForm.value.name,
            customerPhone: contactForm.value.phone,
            message: contactForm.value.message
          })
        });
      }
      showPopup('Đã Gửi Liên Hệ!', 'Yêu cầu liên hệ về "' + selectedItem.value.title + '" đã được ghi nhận. Chủ tin đăng sẽ sớm gọi lại.', 'success');
      showContactModal.value = false;
    };

    const submitNewPost = () => {
      const locName = getDistrictName(postForm.value.district);
      const specs = [];
      if (postForm.value.category === 'tuyendung') {
        if (postForm.value.jobType) specs.push({ label: 'Hình thức', val: postForm.value.jobType });
        if (postForm.value.jobExperience) specs.push({ label: 'Kinh nghiệm', val: postForm.value.jobExperience });
        if (postForm.value.jobGender) specs.push({ label: 'Giới tính', val: postForm.value.jobGender });
        if (postForm.value.jobQuantity) specs.push({ label: 'Số lượng tuyển', val: postForm.value.jobQuantity });
      } else if (postForm.value.category === 'batdongsan') {
        if (postForm.value.bdsType) specs.push({ label: 'Loại hình BĐS', val: postForm.value.bdsType });
        if (postForm.value.bdsArea) specs.push({ label: 'Diện tích', val: postForm.value.bdsArea });
        if (postForm.value.bdsLegal) specs.push({ label: 'Pháp lý', val: postForm.value.bdsLegal });
        if (postForm.value.bdsDirection) specs.push({ label: 'Hướng đất/nhà', val: postForm.value.bdsDirection });
        if (postForm.value.bdsRoad) specs.push({ label: 'Đường vào', val: postForm.value.bdsRoad });
      } else if (postForm.value.category === 'raovat') {
        if (postForm.value.itemCondition) specs.push({ label: 'Tình trạng', val: postForm.value.itemCondition });
        if (postForm.value.itemBrand) specs.push({ label: 'Hãng sản xuất', val: postForm.value.itemBrand });
        if (postForm.value.itemWarranty) specs.push({ label: 'Bảo hành', val: postForm.value.itemWarranty });
      } else if (postForm.value.category === 'suachua') {
        if (postForm.value.serviceScope) specs.push({ label: 'Phạm vi', val: postForm.value.serviceScope });
        if (postForm.value.serviceSpeed) specs.push({ label: 'Thời gian', val: postForm.value.serviceSpeed });
        if (postForm.value.serviceWarranty) specs.push({ label: 'Bảo hành thợ', val: postForm.value.serviceWarranty });
      } else if (postForm.value.category === 'amthuc') {
        if (postForm.value.foodType) specs.push({ label: 'Loại hình', val: postForm.value.foodType });
        if (postForm.value.foodHours) specs.push({ label: 'Giờ mở cửa', val: postForm.value.foodHours });
        if (postForm.value.foodAmenity) specs.push({ label: 'Tiện ích', val: postForm.value.foodAmenity });
      }

      const newCard = {
        id: 'tn_' + Date.now(),
        badge: postForm.value.badge || 'Mới đăng',
        image: postForm.value.imageBase64 || postForm.value.previewUrl || 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=800&q=80',
        title: postForm.value.title,
        subtitle: (postForm.value.address ? postForm.value.address + ' - ' : '') + locName,
        price: postForm.value.price || 'Thỏa thuận',
        subprice: postForm.value.subprice || 'Vừa xong',
        category: postForm.value.category,
        btnType: postForm.value.category === 'tuyendung' ? 'apply' : (postForm.value.category === 'suachua' ? 'call' : 'contact'),
        location: locName,
        district: postForm.value.district,
        description: postForm.value.description,
        specs: specs,
        authorName: postForm.value.contactName || (currentUser.value ? currentUser.value.displayName : 'Phạm Thanh Quang'),
        phone: postForm.value.contactPhone || '0908.123.456',
        authorEmail: currentUser.value ? currentUser.value.email : 'ptquang0968@gmail.com',
        createdAt: new Date().toISOString(),
        likesCount: 1,
        likedByMe: true,
        viewsCount: 1,
        showComments: false,
        newCommentText: '',
        comments: []
      };

      cards.value.unshift(newCard);

      if (db) {
        try {
          setDoc(doc(db, 'listings', newCard.id), newCard)
            .then(() => console.log('Đã lưu bài viết lên Firestore thành công!'))
            .catch(e => console.warn('Sync post to firestore notice:', e));
        } catch (e) {
          console.warn('Firestore setDoc:', e);
        }
      }

      showToast('Đăng tin thành công! Tin của bạn đã hiển thị ngay trên TN Hub.', 'success');
      showPostModal.value = false;

      postForm.value = {
        title: '',
        category: 'tuyendung',
        district: 'tptayninh',
        location: 'TP. Tây Ninh',
        address: '',
        price: '',
        subprice: '',
        badge: 'Tuyển gấp',
        description: '',
        contactName: currentUser.value ? currentUser.value.displayName : '',
        contactPhone: '0908.123.456',
        imageBase64: null,
        previewUrl: ''
      };
    };

    const loginGoogle = async () => {
      try {
        if (!auth) throw new Error('Firebase Auth chưa khởi tạo');
        const provider = new GoogleAuthProvider();
        provider.setCustomParameters({ prompt: 'select_account' });
        const res = await signInWithPopup(auth, provider);
        currentUser.value = {
          uid: res.user.uid,
          displayName: res.user.displayName,
          email: res.user.email,
          photoURL: res.user.photoURL
        };
        showToast('Chào mừng ' + (res.user.displayName || '') + '! Đã đăng nhập Google.', 'success');
        return true;
      } catch (err) {
        console.warn('Login Auth info:', err.message);
        showToast('Đang ở phiên làm việc của ptquang0968@gmail.com', 'info');
        return false;
      }
    };

    const logoutGoogle = async () => {
      try {
        if (auth) await signOut(auth);
        currentUser.value = null;
        showToast('Đã đăng xuất Google thành công.', 'info');
      } catch (e) {
        console.warn('Signout err:', e);
      }
    };

    onMounted(() => {
      if (auth) {
        onAuthStateChanged(auth, (user) => {
          if (user) {
            currentUser.value = {
              uid: user.uid,
              displayName: user.displayName,
              email: user.email,
              photoURL: user.photoURL
            };
          } else {
            currentUser.value = null;
          }
        });
      }

      // LẮNG NGHE REALTIME COLLECTION 'listings' TỪ FIREBASE (100% CLOUD FIRESTORE)
      if (db) {
        try {
          const listingsRef = collection(db, 'listings');
          onSnapshot(listingsRef, (snapshot) => {
            if (!snapshot.empty) {
              // Lưu giữ trạng thái UI hiện tại của từng thẻ
              const stateMap = {};
              cards.value.forEach(c => {
                if (c && c.id) {
                  stateMap[String(c.id)] = {
                    showComments: c.showComments,
                    newCommentText: c.newCommentText
                  };
                  if (c.docId) stateMap[String(c.docId)] = stateMap[String(c.id)];
                  if (c.listingCode) stateMap[String(c.listingCode)] = stateMap[String(c.id)];
                }
              });

              const liveList = [];
              snapshot.forEach((d) => {
                const data = d.data() || {};
                const docId = String(d.id);
                const codeId = data.id ? String(data.id) : docId;
                const rawData = { 
                  ...data, 
                  id: docId, 
                  docId: docId, 
                  listingCode: codeId 
                };
                const enriched = enrichListingWithFirebaseDoc(rawData);

                // Phục hồi trạng thái UI của thẻ
                const prev = stateMap[docId] || stateMap[codeId];
                if (prev) {
                  if (prev.showComments !== undefined) enriched.showComments = prev.showComments;
                  if (prev.newCommentText) enriched.newCommentText = prev.newCommentText;
                }

                // Trạng thái Like của người dùng được xác định 100% chính xác từ likedPosts
                enriched.likedByMe = isLiked(enriched);
                liveList.push(enriched);
              });
              liveList.sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || ''));
              cards.value = liveList;

              // ĐỒNG BỘ REALTIME VÀO MODAL CHI TIẾT NẾU ĐANG MỞ (Không làm tắt modal)
              if (selectedDetailCard.value && selectedDetailCard.value.id) {
                const matched = liveList.find(c => c.id === selectedDetailCard.value.id);
                if (matched) {
                  selectedDetailCard.value.comments = matched.comments;
                  selectedDetailCard.value.likesCount = matched.likesCount;
                  selectedDetailCard.value.viewsCount = matched.viewsCount;
                  if (matched.likedByMe !== undefined) selectedDetailCard.value.likedByMe = matched.likedByMe;
                }
              }

              isFirebaseConnected.value = true;
              isDataLoading.value = false;
              console.log('Đã đồng bộ ' + liveList.length + ' tin đăng realtime từ Cloud Firestore');
            } else {
              isDataLoading.value = false;
            }
          }, (err) => {
            console.warn('Firestore snapshot error:', err);
            isDataLoading.value = false;
          });
        } catch (err) {
          console.warn('Firestore setup error:', err);
          isDataLoading.value = false;
        }

        // LẮNG NGHE REALTIME COLLECTION 'messages' VÀ PHÁT NOTIFICATION
        try {
          const messagesRef = collection(db, 'messages');
          let initialMessagesDone = false;
          onSnapshot(messagesRef, (snapshot) => {
            const liveMsgs = [];
            snapshot.forEach(d => liveMsgs.push({ id: d.id, ...d.data() }));
            liveMsgs.sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || ''));
            if (liveMsgs.length > 0) {
              communityMessages.value = liveMsgs;
            }

            if (initialMessagesDone) {
              snapshot.docChanges().forEach(change => {
                if (change.type === 'added') {
                  const data = change.doc.data();
                  unreadMessageCount.value++;
                  playNotificationSound();
                  showToast('[Tin nhắn mới] ' + (data.senderName || 'Cộng đồng') + ': "' + (data.text ? data.text.substring(0, 45) : '') + '..."', 'success', 'Tin Nhắn Realtime');
                }
              });
            }
            initialMessagesDone = true;
          }, (err) => {
            if (err && err.code === 'permission-denied') {
              console.info('Firestore: Chưa mở quyền đọc cho collection messages trong Rules (có thể bổ sung sau).');
            } else {
              console.warn('Messages snapshot warning:', err);
            }
          });
        } catch (err) {
          console.warn('Messages setup error:', err);
        }
      }
    });

    return {
      displayLimit,
      activeDistrict,
      activePriceRange,
      sortAsc,
      isFirebaseConnected,
      totalFilteredCount,
      isDataLoading,
      hasMoreCards,
      remainingCardsCount,
      loadMore,
      activeTab,
      activeCategory,
      viewMode,
      showMobileMenu,
      searchKeyword,
      userMenuOpen,
      showApplyModal,
      showContactModal,
      showPostModal,
      showDetailModal,
      selectedDetailCard,
      submittingApply,
      selectedItem,
      currentUser,
      bookmarks,
      toasts,
      popup,
      cards,
      filteredCards,
      mapQuickList,
      activePinItem,
      mapEmbedUrl,
      tayNinhVideos,
      activePlayingVideo,
      showVideoPlayerModal,
      playVideo,
      showChatDrawer,
      chatMessageInput,
      unreadMessageCount,
      communityMessages,
      openChatDrawer,
      sendCommunityMessage,
      playNotificationSound,
      formatTime,
      applyForm,
      contactForm,
      postForm,
      showToast,
      removeToast,
      showPopup,
      handlePopupConfirm,
      setCategory,
      filterBookmarks,
      isBookmarked,
      toggleBookmark,
      isLiked,
      likedPosts,
      toggleSort,
      zoomMap,
      onSearchKey,
      selectPin,
      selectCardForMap,
      selectQuickListItem,
      openApplyModal,
      openContactModal,
      openCallModal,
      openDetailModal,
      isAdmin,
      confirmDeletePost,
      executeDeletePost,
      handleImgError,
      openPostModal,
      openPostModalWithCategory,
      toggleLike,
      toggleComments,
      postCardComment,
      likeComment,
      postCommentReply,
      incrementView,
      modalNewCommentText,
      postDetailComment,
      postImageDriveStatus,
      getCategoryLabel,
      getDistrictName,
      getCardDescription,
      fillTemplateDescription,
      selectPresetImage,
      onPostCategoryChange,
      shareCard,
      handleCvUpload,
      handlePostImageUpload,
      submitApplication,
      submitContactInquiry,
      submitNewPost,
      loginGoogle,
      logoutGoogle
    };
  }
}).mount('#app');
//
